#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("wyniki.txt");
    string imie, grupa;
    int wynik;
    map<string, pair<int, string>> minG, maxG;
    while (plik >> imie >> grupa >> wynik) {
        if (minG.find(grupa) == minG.end() || wynik < minG[grupa].first) {
            minG[grupa] = {wynik, imie};
        }
        if (maxG.find(grupa) == maxG.end() || wynik > maxG[grupa].first) {
            maxG[grupa] = {wynik, imie};
        }
    }
    for (auto& g : minG) {
        cout << "Grupa " << g.first << ":" << endl;
        cout << "   Min: " << g.second.second << " (" << g.second.first << ")" << endl;
        cout << "   Max: " << maxG[g.first].second << " (" << maxG[g.first].first << ")" << endl;
    }
    return 0;
}
```

